  notes text,
  created_by uuid,
  created_at timestamp with time zone not null,
  sales_rep_id uuid,
  sales_rep_name text
);

create table if not exists public.consignment_inventory (
  id uuid not null,
  partner_id uuid not null,
  product_id uuid not null,
  product_code text,
  product_name text not null,
  category text,
  unit text not null,
  delivered_qty numeric not null,
  sold_qty numeric not null,
  returned_qty numeric not null,
  remaining_qty numeric not null,
  unit_price numeric not null,
  last_dispatch_at timestamp with time zone,
  updated_at timestamp with time zone not null
);

create table if not exists public.consignment_items (
  id uuid not null,
  consignment_id uuid,
  product_id uuid,
  sent_qty numeric(12,2),
  sold_qty numeric(12,2),
  returned_qty numeric(12,2),
  remaining_qty numeric(12,2),
  unit_price numeric(12,2) not null
);

create table if not exists public.consignment_monthly_reports (
  id uuid not null,
  report_no text not null,
  partner_id uuid not null,
  report_period text not null,
  sold_items jsonb not null,
