  invoice_id uuid,
  notes text,
  created_by uuid,
  created_at timestamp with time zone not null,
  sales_rep_id uuid,
  sales_rep_name text,
  returned_items jsonb not null
);

create table if not exists public.consignment_orders (
  id uuid not null,
  customer_name character varying(255) not null,
  seller_name character varying(255),
  order_date date,
  created_at timestamp with time zone
);

create table if not exists public.consignment_partners (
